// This file is hand written and is not regenerated by `go generate
// ./internal/ent`: it provides OpenEmbedded, the on-disk SQLite entry point
// a Walk-tier composition root (a CLI, no server) uses to get a durable
// store with zero external infrastructure, no Postgres, no NATS, just a
// file on disk.
package ent

import (
	"context"
	stdsql "database/sql"
	"fmt"
	"net/url"
	"os"
	"path/filepath"

	"entgo.io/ent/dialect"
	entsql "entgo.io/ent/dialect/sql"

	"github.com/Subject-Void-LLC/the-pleiades/internal/ent/migrate"
	// Registers the "sqlite3" database/sql driver this file's stdsql.Open
	// call names. Every existing test reaches OpenEmbedded only through a
	// _test.go file that imports this driver itself, so this gap was
	// invisible until archtest's adapter-allowlist check asked "does this
	// package actually import a concrete driver" and the honest answer
	// was no: OpenEmbedded has no production caller yet (Phase 2+'s
	// composition root is what will add one), and without this import the
	// real pleiades binary would fail with "unknown driver \"sqlite3\""
	// the first time one did.
	_ "github.com/mattn/go-sqlite3"
)

// embeddedBusyTimeoutMillis is how long a single connection waits on a
// locked database before giving up, in milliseconds. WAL mode (see
// embeddedDSN) already lets any number of readers proceed concurrently with
// the one writer, so contention is rare in an embedded single-process
// deployment; this timeout only matters for the brief window two writers
// overlap, and five seconds is generous enough to absorb that without a
// caller seeing SQLITE_BUSY.
const embeddedBusyTimeoutMillis = 5000

// OpenEmbedded opens an ent Client backed by a real on-disk SQLite file at
// path, applies every pending versioned migration, and returns the client
// ready for use. It is the entry point a Walk-tier composition root (a CLI
// with no server component) calls to get a durable store without standing
// up any external infrastructure.
//
// The parent directory of path is created if it does not already exist,
// since a freshly scaffolded project directory will not have one yet.
//
// Migration is idempotent and fails closed: internal/ent/migrate.Apply
// records each committed migration file as it applies it, so calling
// OpenEmbedded again against a file that already has every migration
// applied is a clean no-op, and calling it against a file whose recorded
// history this binary's embedded migrations do not recognize (or that has
// a gap in an already-applied prefix) returns an error instead of silently
// proceeding against a schema shape that was never verified. This replaced
// ent's automatic Schema.Create diff-and-apply, which had no such gate and
// no committed record of what had actually been run.
//
// The returned Client must be closed by the caller (Client.Close) once it
// is no longer needed.
func OpenEmbedded(ctx context.Context, path string) (*Client, error) {
	// A bare filename (or the empty string) has no parent directory beyond
	// ".", which always exists, so MkdirAll is only needed, and only
	// meaningful, when Dir names something else.
	if dir := filepath.Dir(path); dir != "." {
		// 0o750, not 0o755: this directory holds the embedded state
		// database (device inventory, revision history), so it gets the
		// same owner-and-group-only posture as the credential store's
		// directory in internal/credential, not the world-readable
		// default a plain MkdirAll would otherwise leave it at.
		if err := os.MkdirAll(dir, 0o750); err != nil {
			return nil, fmt.Errorf("ent: creating parent directory for embedded database %q: %w", path, err)
		}
	}

	// Open the raw driver first so the migration runner can run plain SQL
	// against it before any ent-generated query touches the connection.
	db, err := stdsql.Open(dialect.SQLite, embeddedDSN(path))
	if err != nil {
		return nil, fmt.Errorf("ent: opening embedded database %q: %w", path, err)
	}

	if err := migrate.Apply(ctx, dialect.SQLite, db); err != nil {
		// Close the half-opened database on the error path so its file
		// descriptor is not leaked back to the caller.
		if cerr := db.Close(); cerr != nil {
			return nil, fmt.Errorf("ent: migrating embedded database %q: %w (also failed to close: %v)", path, err, cerr)
		}
		return nil, fmt.Errorf("ent: migrating embedded database %q: %w", path, err)
	}

	// Wrap the same, already-migrated connection in the ent client rather
	// than opening a second one, so migration and every later query share
	// one connection pool against the same file.
	drv := entsql.OpenDB(dialect.SQLite, db)
	return NewClient(Driver(drv)), nil
}

// embeddedDSN builds the mattn/go-sqlite3 data source name for a durable,
// single-process embedded database at path. Parameter names and behavior
// were verified directly against github.com/mattn/go-sqlite3 v1.14.49's own
// source (its Open method's doc comment and query-parameter handling)
// rather than assumed:
//
//   - "_fk=1" enables foreign key constraint enforcement, matching the
//     spelling this codebase already uses in client_test.go and enttest.go.
//   - "_journal_mode=WAL" puts the database in write-ahead-log mode, so
//     readers never block the writer and vice versa. This matters here
//     specifically because an embedded process may hold the client open for
//     the CLI's whole lifetime while issuing many small transactions.
//   - "_busy_timeout" (milliseconds) makes a connection wait, rather than
//     immediately fail with SQLITE_BUSY, on the rare occasion two writers
//     do overlap.
func embeddedDSN(path string) string {
	// The path is percent-escaped through url.URL's path escaping (not
	// url.PathEscape, which also escapes '/' and would place every path
	// separator into the query-string-adjacent part of the DSN). This keeps
	// '/' literal while still escaping characters such as space, '?', and
	// '#' that would otherwise be misread as the start of the DSN's query
	// string or fragment by either go-sqlite3's own DSN splitting or
	// SQLite's own URI-filename grammar. SQLite percent-decodes the path
	// component of a "file:" URI before using it, so the escaped form still
	// resolves to the exact literal path passed in.
	escaped := (&url.URL{Path: path}).EscapedPath()
	return fmt.Sprintf("file:%s?_fk=1&_journal_mode=WAL&_busy_timeout=%d", escaped, embeddedBusyTimeoutMillis)
}
